arguments.content:
:root {
  --bg-base: #0F0F0F;
  --bg-surface: #1a1a2e;
  --bg-surface-alt: #232338;
  --bg-hover: #2a2a44;
  --text-primary: #E0E0E0;
  --text-secondary: #9090A0;
  --accent-blue: #2962FF;
  --accent-green: #089981;
  --accent-red: #F7525F;
  --border-color: #2B2B36;
  --font-family: 'Inter', 'DM Sans', -apple-system, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-family);
  background-color: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.5;
  font-size: 14px;
}

a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; color: inherit; }

/* Layouts */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
}

header {
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-base);
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 60px;
}

.brand {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.brand span { color: var(--accent-blue); }

.nav-links {
  display: flex;
  gap: 24px;
}

.nav-links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
}

.nav-actions {
  display: flex;
  gap: 12px;
}

.btn {
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 14px;
  transition: all 0.2s;
}

.btn-primary {
  background: var(--accent-blue);
  color: #fff;
}
.btn-primary:hover { background: #1E4EED; }

.btn-secondary {
  background: var(--bg-surface-alt);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover { background: var(--bg-hover); }

.positive { color: var(--accent-green); }
.negative { color: var(--accent-red); }

/* Tabs */
.tabs {
  display: flex;
  gap: 16px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 20px;
  overflow-x: auto;
}

.tab {
  padding: 12px 0;
  color: var(--text-secondary);
  font-weight: 500;
  position: relative;
}

.tab.active {
  color: var(--text-primary);
}

.tab.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-blue);
}

.tab:hover { color: var(--text-primary); }

.tab-content { display: none; }
.tab-content.active { display: block; }

/* Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.data-table th, .data-table td {
  padding: 12px 16px;
  text-align: right;
  border-bottom: 1px solid var(--border-color);
}

.data-table th:first-child, .data-table td:first-child { text-align: left; }

.data-table th {
  color: var(--text-secondary);
  font-weight: 500;
}

.data-table tbody tr:hover {
  background: var(--bg-surface);
}

.mini-chart {
  width: 60px;
  height: 20px;
  display: inline-block;
  background: linear-gradient(90deg, transparent 50%, var(--bg-surface-alt) 50%);
  border-bottom: 1px solid;
}
.mini-chart.up { border-color: var(--accent-green); }
.mini-chart.down { border-color: var(--accent-red); }

/* Footer */
footer {
  border-top: 1px solid var(--border-color);
  padding: 60px 0;
  margin-top: 60px;
  background: var(--bg-base);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
}

.footer-col h4 {
  color: var(--text-primary);
  margin-bottom: 16px;
  font-size: 15px;
}

.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 12px; }
.footer-col a { color: var(--text-secondary); font-size: 14px; }
.footer-col a:hover { color: var(--accent-blue); }

/* Utilities */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 20px;
}
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.mt-2 { margin-top: 8px; }
.mt-4 { margin-top: 16px; }
.mt-8 { margin-top: 32px; }
.mb-2 { margin-bottom: 8px; }
.mb-4 { margin-bottom: 16px; }
.mb-8 { margin-bottom: 32px; }
.text-sm { font-size: 12px; }
.text-lg { font-size: 18px; }
.text-xl { font-size: 24px; }
.font-bold { font-weight: 700; }
.text-secondary { color: var(--text-secondary); }

/* Responsive */
@media (max-width: 768px) {
  .nav-links { display: none; }
}

arguments.command:
cat << 'EOF' >> /app/output/styles.css

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }

/* Dashboard Layout */
.dashboard-layout {
  display: flex;
  height: calc(100vh - 60px);
  overflow: hidden;
}

.main-content {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
}

.sidebar {
  width: 320px;
  border-left: 1px solid var(--border-color);
  background: var(--bg-surface);
  display: flex;
  flex-direction: column;
}

/* Home Page specific */
.hero {
  text-align: center;
  padding: 80px 20px;
}

.hero h1 {
  font-size: 48px;
  margin-bottom: 24px;
  line-height: 1.2;
}

.hero p {
  font-size: 20px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
}

/* Summary Bar */
.summary-bar {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-color);
}
.summary-item {
  display: flex;
  flex-direction: column;
  min-width: 120px;
}
.summary-name { font-size: 12px; color: var(--text-secondary); }
.summary-price { font-size: 14px; font-weight: 600; }
.summary-change { font-size: 12px; }

/* Watchlist Accordion */
.accordion-header {
  padding: 12px 16px;
  background: var(--bg-surface-alt);
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-color);
}
.accordion-content {
  display: block;
}
.accordion-content.hidden {
  display: none;
}
.watchlist-item {
  display: flex;
  justify-content: space-between;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border-color);
}
.watchlist-item:hover { background: var(--bg-hover); }

/* Chart Area */
.chart-container {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  height: 500px;
  position: relative;
  display: flex;
  flex-direction: column;
}
.chart-toolbar {
  display: flex;
  gap: 8px;
  padding: 12px;
  border-bottom: 1px solid var(--border-color);
}
.chart-btn {
  padding: 4px 8px;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 12px;
}
.chart-btn.active {
  background: var(--accent-blue);
  color: white;
  border-color: var(--accent-blue);
}
.chart-main {
  flex: 1;
  position: relative;
  overflow: hidden;
}

/* Ideas Feed */
.idea-card {
  display: flex;
  gap: 20px;
  padding: 20px;
  border-bottom: 1px solid var(--border-color);
}
.idea-img {
  width: 200px;
  height: 120px;
  background: var(--bg-surface-alt);
  border-radius: 8px;
}
.idea-content {
  flex: 1;
}

/* Brokers */
.broker-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  margin-bottom: 16px;
}
.broker-info { display: flex; gap: 20px; align-items: center; }
.broker-logo {
  width: 60px; height: 60px; background: #fff; border-radius: 8px;
}
.tier-badge {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}
.tier-platinum { background: linear-gradient(135deg, #e5e4e2, #b0b0b0); color: #000; }
.tier-gold { background: linear-gradient(135deg, #ffd700, #daa520); color: #000; }

.badge-green { background: rgba(8, 153, 129, 0.2); color: var(--accent-green); padding: 4px 8px; border-radius: 4px; font-size: 12px; }

EOF

arguments.content:
document.addEventListener('DOMContentLoaded', () => {

  // Simple Tab System
  const setupTabs = (tabGroupSelector, contentGroupSelector) => {
    const tabs = document.querySelectorAll(tabGroupSelector);
    if (!tabs.length) return;

    tabs.forEach(tab => {
      tab.addEventListener('click', (e) => {
        // Prevent default if it's an anchor
        if(e.target.tagName === 'A' && e.target.getAttribute('href') === '#') {
          e.preventDefault();
        }

        // Remove active class from all tabs in this group
        const group = tab.parentElement;
        group.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));

        // Add active class to clicked tab
        tab.classList.add('active');

        // Handle content switching if content target is specified
        const targetId = tab.dataset.target;
        if (targetId) {
          const contentItems = document.querySelectorAll(contentGroupSelector);
          contentItems.forEach(item => item.classList.remove('active'));

          const targetEl = document.getElementById(targetId);
          if (targetEl) targetEl.classList.add('active');
        }
      });
    });
  };

  // Setup multiple tab groups
  setupTabs('.home-market-tabs .tab', '.home-market-content');
  setupTabs('.home-ideas-tabs .tab', '.home-ideas-content');
  setupTabs('.home-indicators-tabs .tab', '.home-indicators-content');
  setupTabs('.chart-detail-tabs .tab', '.chart-detail-content');
  setupTabs('.ideas-filter-tabs .tab', '.ideas-feed-content');
  setupTabs('.markets-asset-tabs .tab', '.markets-asset-content');
  setupTabs('.markets-stock-gainers-tabs .tab', '.markets-stock-gainers-content');
  setupTabs('.brokers-category-tabs .tab', '.brokers-category-content');
  setupTabs('.brokers-rating-tabs .tab', '.brokers-rating-content');

  // Chart Timeframe & Type Toggles
  const setupToggles = (selector) => {
    const btns = document.querySelectorAll(selector);
    btns.forEach(btn => {
      btn.addEventListener('click', () => {
        btn.parentElement.querySelectorAll(selector).forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
      });
    });
  };
  setupToggles('.chart-btn');

  // Watchlist Accordion
  const headers = document.querySelectorAll('.accordion-header');
  headers.forEach(header => {
    header.addEventListener('click', () => {
      const content = header.nextElementSibling;
      if (content.classList.contains('hidden')) {
        content.classList.remove('hidden');
        header.querySelector('.icon').textContent = '▼';
      } else {
        content.classList.add('hidden');
        header.querySelector('.icon').textContent = '▶';
      }
    });
  });

  // Ideas Video Toggle
  const videoToggle = document.getElementById('video-toggle');
  if (videoToggle) {
    videoToggle.addEventListener('change', (e) => {
      const feedItems = document.querySelectorAll('.idea-card');
      if (e.target.checked) {
        feedItems.forEach(item => {
          if (!item.dataset.hasVideo) item.style.display = 'none';
        });
      } else {
        feedItems.forEach(item => {
          item.style.display = 'flex';
        });
      }
    });
  }

  // Navigation for market asset tabs that scroll to sections
  const assetTabs = document.querySelectorAll('.scroll-tab');
  assetTabs.forEach(tab => {
    tab.addEventListener('click', (e) => {
      e.preventDefault();
      const targetId = tab.dataset.scrollTarget;
      if(targetId) {
        const el = document.getElementById(targetId);
        if(el) {
          el.scrollIntoView({ behavior: 'smooth' });
          assetTabs.forEach(t => t.classList.remove('active'));
          tab.classList.add('active');
        }
      }
    });
  });
});
